-- Initial schema (generated from the JPA entities for PostgreSQL).
-- Existing databases are baselined at V1 (spring.flyway.baseline-on-migrate).

create table donors (created_at timestamp(6) not null, fundraiser_id bigint not null, id bigint generated by default as identity, email varchar(255) not null, first_name varchar(255) not null, last_name varchar(255) not null, phone varchar(255), primary key (id));
create table evidences (assignment_id bigint, created_at timestamp(6) not null, fundraiser_id bigint not null, id bigint generated by default as identity, receipt_number varchar(50), attachment_url varchar(500), recipient_feedback varchar(1000), primary key (id));
create table fund_representatives (fund_id bigint not null, id bigint generated by default as identity, phone varchar(20) not null, first_name varchar(50) not null, last_name varchar(50) not null, email varchar(100) not null, password_hash varchar(255) not null, primary key (id), constraint uk_fund_representatives_email unique (email));
create table fundraiser (closed_at timestamp(6), created_at timestamp(6) not null, id bigint generated by default as identity, request_id bigint, status varchar(255) check ((status in ('PENDING_ASSIGNMENT','IN_PROGRESS','CLOSED'))), primary key (id));
create table fundraiser_assignment (assigned_at timestamp(6), finished_at timestamp(6), fundraiser_id bigint, id bigint generated by default as identity, volunteer_id bigint, return_reason varchar(255), status varchar(255) check ((status in ('ACTIVE','RETURNED','COMPLETED'))), primary key (id));
create table funds (edrpou varchar(8) not null, id bigint generated by default as identity, phone_number varchar(20) not null, status varchar(20) not null check ((status in ('PENDING_APPROVAL','APPROVED','REJECTED'))), corp_email varchar(100) not null, fund_name varchar(150) not null, bank_detail varchar(500) not null, description varchar(2000), actual_address varchar(255) not null, registered_address varchar(255) not null, website varchar(255) not null, social_media_urls jsonb, primary key (id), constraint uk_funds_edrpou unique (edrpou));
create table mailing_recipient (id bigint generated by default as identity, sent_at timestamp(6), task_id bigint not null, email varchar(255) not null, error_message TEXT, status varchar(255) not null check ((status in ('PENDING','SENT','ERROR'))), primary key (id));
create table mailing_task (created_at timestamp(6) not null, finished_at timestamp(6), fundraiser_id bigint, id bigint generated by default as identity, message_body TEXT not null, status varchar(255) not null check ((status in ('PENDING','PROCESSING','COMPLETED','FAILED'))), subject varchar(255) not null, primary key (id));
create table request_documents (id bigint generated by default as identity, request_id bigint not null, file_name varchar(255) not null, file_url varchar(255) not null, primary key (id));
create table requests (amount numeric(19,2) not null, data_processing_consent boolean not null, deadline date not null, created_at timestamp(6) not null, fund_id bigint, id bigint generated by default as identity, user_id bigint not null, version bigint not null, need_description varchar(1000) not null, situation_description varchar(1000) not null, application_number varchar(255) not null, assistance_type varchar(255) not null, institution_name varchar(255) not null, status varchar(255) not null check ((status in ('PENDING_VERIFICATION','NEW','IN_PROGRESS','CLOSED'))), primary key (id));
create table system_admins (id bigint generated by default as identity, first_name varchar(50) not null, last_name varchar(50) not null, email varchar(100) not null, password_hash varchar(100) not null, primary key (id), constraint uk_system_admins_email unique (email));
create table users (id bigint generated by default as identity, email varchar(255), first_name varchar(255), last_name varchar(255), primary key (id));
create table verification_acts (date_of_verification date not null, fund_id bigint not null, id bigint generated by default as identity, system_admin_id bigint not null, decision varchar(20) not null check ((decision in ('PENDING_APPROVAL','APPROVED','REJECTED'))), comment varchar(1000), primary key (id));
create table volunteers (fund_id bigint not null, id bigint generated by default as identity, email varchar(255) not null, first_name varchar(255) not null, last_name varchar(255) not null, phone varchar(255) not null, status varchar(255) not null check ((status in ('ACTIVE','INACTIVE'))), primary key (id));
